  #undef rwallthick
  #undef lwallthick
  #undef uwallthick
  #undef dwallthick
  #undef w1rwt
  #undef w1lwt
  #undef h1uwt
  #undef h1dwt
  #undef w2rwt
  #undef w2lwt
